#!/usr/bin/env bash
# SAHA_NARRATIVE_V5 deploy — kirilgan JSON.parse -> tool-calling (parse hatasi biter). Analist paragraf + isimli baglanti.
#   Bu, "ozet bu tur olusmadi" fallback'inin KOK NEDENINI cozer: model artik garantili gecerli cikti veriyor.
set -e
cd /opt/krb-assessment
SRV=server_container.mjs
[ -f "$SRV" ] || { echo "HATA: $SRV yok"; exit 1; }
TS=$(date +%s)
cp "$SRV" "$SRV.bak.$TS"; echo "yedek: $SRV.bak.$TS"
printf '%s' '' | base64 -d > /tmp/patch_saha_narrative_v5.py
python3 /tmp/patch_saha_narrative_v5.py "$SRV"
if ! node --check "$SRV"; then echo "!! node --check BASARISIZ — geri aliniyor"; cp "$SRV.bak.$TS" "$SRV"; exit 1; fi
echo "node --check: OK"
cp shells/kokpit2.html "shells/kokpit2.html.bak.$TS"
printf '%s' '' | base64 -d > shells/kokpit2.html
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 5
echo "== hata log kontrol (parse hatasi ARTIK OLMAMALI) =="
docker logs krb-assessment --since 1m 2>&1 | grep -iE "saha-sesi" | tail -5 || echo "(saha-sesi log yok — iyi)"
echo "== /api/bi/kokpit2 -> Bolum 05: gercek analist yorumu (paragraf) + isimli baglantilar. Ilk acilis birkac sn (yeniden uretilir). =="
echo "== DONE =="
